import {
  addToScene,
  createPcfDirectionalShadowGenerator,
  setShadowGeneratorEnabled,
} from "@babylonjs/lite";
import type { DirectionalLight, EngineContext, SceneContext, ShadowGenerator } from "@babylonjs/lite";

// One generator per sun, so calling addSunShadows twice does not create a second shadow map.
const generatorBySun = new WeakMap<DirectionalLight, ShadowGenerator>();

export function addSunShadows(engine: EngineContext, scene: SceneContext, sun: DirectionalLight): ShadowGenerator {
  // Put the sun in the scene, once.
  if (!scene.lights.includes(sun)) {
    addToScene(scene, sun);
  }

  let sg = generatorBySun.get(sun);
  if (!sg) {
    sg = createPcfDirectionalShadowGenerator(engine, sun, {
      mapSize: 2048,
      // Re-render the shadow map on every shadow pass, so moving casters are never shown stale.
      forceRefreshEveryFrame: true,
    });
    generatorBySun.set(sun, sg);
  }

  // Make sure the shadow pass includes this generator, and that it is enabled.
  if (!scene.shadowGenerators.includes(sg)) {
    addToScene(scene, sg);
  }
  setShadowGeneratorEnabled(sg, true);

  sun.shadowGenerator = sg;
  return sg;
}
```

I did what you asked in the code above, with these points I'm not sure of:

- **Import paths:** I assumed `addToScene`, `createPcfDirectionalShadowGenerator` and `setShadowGeneratorEnabled` are exported from the `@babylonjs/lite` root. The declarations only show them at internal paths (`scene/scene-core.d.ts`, `shadow/pcf-directional-shadow-generator.d.ts`, `shadow/shadow-enabled.d.ts`), so check the package's exports.
- **Shadow pass wiring:** I assumed that adding the generator to `scene.shadowGenerators` and setting `forceRefreshEveryFrame` is what makes the shadow pass render this map each time. The declarations don't document how the pass finds generators, so this is unverified.
- **Running scene:** I don't know whether `addToScene` works on a scene that is already built and running, or whether a rebuild is needed.
- **Linkage:** I set `sun.shadowGenerator` myself; I'm not sure the factory does this already, or whether it is harmful to do it twice.
- **Bias:** I left the bias and normal-bias settings at their defaults, which may cause acne or peter-panning in your scene.
- **Not checked:** Nothing was compiled or run, since the library isn't on this machine.
